INSERT INTO `movie` VALUES (1,1064213,'Anora','Anora','A young sex worker from Brooklyn gets her chance at a Cinderella story when she meets and impulsively marries the son of an oligarch. Once the news reaches Russia, her fairytale is threatened as his parents set out to get the marriage annulled.','2024-10-14','en','/qh8m8Udz0sCa5gy9VaqfHPh0yPM.jpg','/87GU2ifjNYtgYtcRH1NNH1P4ODo.jpg',0,0,7.1,1666,34.869,'[18,35,10749]'),(2,950396,'The Gorge','The Gorge','Two highly trained operatives grow close from a distance after being sent to guard opposite sides of a mysterious gorge. When an evil below emerges, they must work together to survive what lies within.','2025-02-13','en','/7iMBZzVZtG0oBug4TfqDb9ZxAOa.jpg','/9nhjGaFLKtddDPtPaX5EmKqsWdH.jpg',0,0,7.771,1882,45.448,'[10749,878,53]'),(3,1126166,'Flight Risk','Flight Risk','A U.S. Marshal escorts a government witness to trial after he\'s accused of getting involved with a mob boss, only to discover that the pilot who is transporting them is also a hitman sent to assassinate the informant. After they subdue him, they\'re forced to fly together after discovering that there are others attempting to eliminate them.','2025-01-22','en','/q0bCG4NX32iIEsRFZqRtuvzNCyZ.jpg','/gFFqWsjLjRfipKzlzaYPD097FNC.jpg',0,0,6.1,453,43.199,'[28,53,80]'),(4,1212855,'Fight or Flight','Fight or Flight','A mercenary takes on the job of tracking down a target on a plane but must protect her when they\'re surrounded by people trying to kill both of them.','2025-03-13','en','/x4nWnfgJvL045rcUCSJzfgIIY9i.jpg','/6J259Zuq09Bt2PLUNeTS5a3DwLZ.jpg',0,0,6.6,14,24.311,'[28,53]'),(5,1286663,'Control Freak','Control Freak','A motivational speaker, plagued by an uncontrollable itch on her head, becomes infected with a parasitic demon from her homeland.','2025-03-13','en','/kmQb07CrOddVGV0Q73aeU4e8I18.jpg','/zdNiCWClNFjFvl8KQ5sTlOKmBAB.jpg',0,0,6,7,24.99,'[27]'),(6,822119,'Captain America: Brave New World','Captain America: Brave New World','After meeting with newly elected U.S. President Thaddeus Ross, Sam finds himself in the middle of an international incident. He must discover the reason behind a nefarious global plot before the true mastermind has the entire world seeing red.','2025-02-12','en','/pzIddUEMWhWzfvLI3TwxUG2wGoi.jpg','/ywe9S1cOyIhR5yWzK7511NuQ2YX.jpg',0,0,6.17,1004,24.033,'[28,53,878]'),(7,696506,'Mickey 17','Mickey 17','Unlikely hero Mickey Barnes finds himself in the extraordinary circumstance of working for an employer who demands the ultimate commitment to the job… to die, for a living.','2025-02-28','en','/edKpE9B5qN3e559OuMCLZdW1iBZ.jpg','/hNA73rnG4PjSwgojaC2gbO1f8Rt.jpg',0,0,7,502,23.54,'[878,35,12]'),(8,1063873,'Queen Mom','Reine Mère','Amel and her family learn that their landlord wants to get his apartment back in a few months. While Mouna, her eldest daughter, begins to have visions of Charles Martel, and their request for new social housing drags on, Amel has no choice but to reinvent herself.','2025-03-12','fr','/87aEXQKCoLZcKoKsFlIdaZTrnfb.jpg','/jRc117FA9lUn12S3NDFpvEFrxMJ.jpg',0,0,10,1,13.82,'[18,35]'),(9,1430968,'Idiotka','Idiotka','In West Hollywood’s Russian district, Margarita lives out the American Dream: competing on a reality show. Will she slay, serve, or survive?','2025-03-12','en','/62iTZ8qg6QVq68ZiLqRMWpeQXjA.jpg','/oiPQOyHuTA84crxarTkVTObbRz4.jpg',0,0,7,3,13.757,'[35]'),(10,1171153,'Köln 75','Köln 75','Behind one of the best-selling jazz records of all time, Keith Jarrett’s 1975 Köln Concert, how it almost didn’t happen, and how one formidable German teenager, Vera Brandes, breaks every boundary to set the conditions for the creation of a masterpiece. Vera, still in high school when she started producing and promoting music concerts in Cologne, puts everything on the line to put on this show. But Vera believes in the power of music, and she’s never seen anyone play like Keith Jarrett before.','2025-03-13','de','/6ZvdCexhNarRsZVDShialfsK5lf.jpg','/mAuqcQLRqliNatDF9R4a3dz7sss.jpg',0,0,0,0,22.924,'[18]'),(11,1182088,'The Best Friend','O Melhor Amigo','Two great friends meet again after five years. Among so many things that have changed, the resumption of the bond awakens an old feeling for which they remain unprepared.','2025-03-13','pt','/dRzRvvQZE9XfGSTDm2rgolG6e3j.jpg','/eKUcoySFWU8BAWTYaLHcalg9KDR.jpg',0,0,4,1,22.902,'[18,10749,10402]'),(12,1216662,'Somebody','침범','Swimming instructor, Young-eun is a single mom raising her 7-year-old daughter, So-hyun. However, a series of tragic events happens as So-hyun\'s puppy falls from the apartment and dies, and So-hyun bullies other kids in school. Despite her mom\'s earnest efforts to address So-hyun\'s mental disorder, her peculiar behavior persists. Twenty years later, Min, who works in handling unclaimed deaths, meets a new colleague, Hae-young, and they form a close bond. However, as Hae-young warmly integrates herself into Min\'s life, Min begins to feel uncomfortable and suspicious about her intentions.','2025-03-12','ko','/u5UTPTak8pCMXN8zTfWXeE6SlEj.jpg','/cS3XRGttTVC4YPIyOC3jByznpG0.jpg',0,0,0,0,13.68,'[9648,53,18]'),(13,1119820,'The Return from the Other Planet','The Return from the Other Planet','In 1945, a few months after his release from Auschwitz, Yechiel De-Nur, still in his striped jacket, sat down and started writing. After two weeks, he was reborn as Ka-Tzetnik, “the man from the camps.” The books that he wrote were translated into 32 languages and sold millions, while the author himself hid behind the pseudonym Ka-Tzetnik. At the trial of Adolf Eichmann in 1961 his revelatory testimony revealed his true identity as he described Auschwitz as “the other planet,” a place outside of human judgment. Years later, undergoing an experimental LSD treatment for trauma, he revisits his experience, imagining himself as a SS officer, and that changes everything.','2025-03-13','he','/qaOhBUAJVpFl8zSCXX1qySsydcI.jpg','/dci3b1dC8PX3P5ZXnO7v6mjRcpC.jpg',0,0,0,0,22.8,'[]'),(14,1214130,'Stitch Head','Stitch Head','Follows Stitch Head, a small creature awoken by a Mad Professor in a castle to protect the professor\'s other creations from the townspeople of Grubbers Nubbin.','2025-03-12','en','/qwhscpTQAGrpit1ARQvvrlijp8h.jpg','/hNdD8w6OGgISCGBER9exiKoOizr.jpg',0,0,0,0,13.672,'[16,10751]'),(15,1127648,'Bonjour Tristesse','Bonjour Tristesse','At the height of summer, 18-year-old Cécile is languishing by the French seaside with her handsome father, Raymond, and his lover, Elsa, when the arrival of her late mother\'s friend Anne changes everything.','2025-03-13','en','/1yYSUbWs11mjl0s7bjRH8gywKQS.jpg','/2r3b7XSYr9OfIaKyXmiaFNJc4oh.jpg',0,0,0,0,22.779,'[18,10749]'),(16,1130863,'Belle','Belle','A couple have a peaceful existence in a small provincial town. He is a teacher and she runs an opticians practical. Their life is turned upside when Belle, a friend’s daughter who is lodging with them, is found dead in her room.  The husband becomes the prime suspect as the only one at home at the time.','2025-03-13','fr','/5YITitG67kcHNUDJdP5XodlkTlm.jpg','/qkswMUEGRIiPIEf9hFnhPnUbXCN.jpg',0,0,0,0,22.775,'[53,18]'),(17,1084353,'Chinatown Cookout','Chinatown Cookout','Two runaway chefs risk everything they have to start a new life.','2025-03-12','en','/3FKGEuDaNfCNemqo5ixWlYvnc92.jpg','',0,0,0,0,13.621,'[18]'),(18,1317096,'Mulu Nakru','มูลู หน้าครู','May, a young architect who has just moved into her new house in the suburbs with her boyfriend Gun, got news of the death of her stepmother, Po. Only Noon, Po\'s daughter, testifies that someone killed her mother, however, there does not appear to be any clear evidence.  After May decided to take care Noon at her house, Noon has abnormal symptoms as if she had been possessed by a ghost. Whereas May herself, she began to have inability to sleep cause her illness. Gun then asked Chok, Sak and Master Khom to help.  Master Khom immediately realized that there were “black magic” from the past inside her house, he asked all to find the source of this evil. There is a misfortune in the past related to the The Master\'s Facial Skin which was removed by Master Jong who is another disciple from his same sect was the source of all these horrifying stories.','2025-03-13','th','/y1aTtWkMjgKgkNa6Zxs3kmxje21.jpg','',0,0,0,0,22.699,'[27,18]'),(19,1416331,'Mechanisms','Mechanisms','Everyone has their own way.','2025-03-12','en','/zSLQaw725EVLKPz4WicCEqk2bSw.jpg','',0,0,0,0,13.604,'[18]'),(20,1418350,'Hojo','호조','','2025-03-12','ko','/mHnCmq6quEVdRdx049AqsBTqfnV.jpg','/cVhwzEt0ED65buC76QLi58zZt9J.jpg',0,0,0,0,13.6,'[36,18]'),(21,823219,'Flow','Straume','A solitary cat, displaced by a great flood, finds refuge on a boat with various species and must navigate the challenges of adapting to a transformed world together.','2024-08-29','lv','/imKSymKBK7o73sajciEmndJoVkR.jpg','/b3mdmjYTEL70j7nuXATUAD9qgu4.jpg',0,0,8.288,1507,22.528,'[16,14,12]'),(22,1216571,'June and John','June et John','The story of John, a man who leads an ordinary life with a monotonous routine. His existence flows away dull, and he himself makes no effort to change anything; on the contrary, he does everything to continue being an ordinary man.  One day John runs into a woman on the subway who is as beautiful as she is mysterious named June. His encounter with her finally leads him to have a goal in his bumptious life: to love June to the end of his days and at any cost.','2025-03-13','fr','/fuGPUHzYq4ssMPBM2Gn8X9QKqCr.jpg','/xiBr5BQmIjI8rAcMRAc6XkS4Wav.jpg',0,0,0,0,22.526,'[10749,53]'),(23,1400932,'Youth Eternal','Mūžīgi jauni','A coming of age story about a group of millennials who start to face their self-destructive tendencies as they each head straight into their crisis of thirtysomethings.','2025-03-13','lv','/zSXPnFB68yEokjRf4Ss2Y5F6toZ.jpg','/lFmLxg61GXGCYowoQn0gSdZUQHI.jpg',0,0,0,0,22.489,'[18]'),(24,1404172,'Sandbag Dam','Zečji nasip','A story about a forbidden love set in a village threatened by swollen rivers. Upon his return home for his father’s funeral, Slaven revives his relationship with his childhood friend, a young sportsman named Marko, his teenage love, and the reason his father kicked him out of the house. Now tempted to reunite, they need to make peace with their own decisions and struggle against the family restraints.','2025-03-13','hr','/3jwR4NtikY53SO5agejuEYEzoh3.jpg','/32OKhnDgNyQFKlIMnefm9RbVKHs.jpg',0,0,0,0,22.48,'[18]'),(25,1412392,'Samar: Diam Atau Mati','Samar: Diam Atau Mati','Horror film about the negative impact of bullying in public schools','2025-03-13','id','','',0,0,0,0,22.461,'[]'),(26,1077281,'Couples to Hell','커플지옥','A couple is kidnapped by a serial killer on their first anniversary. The kidnapper forces the couple to play a twisted game of rock paper scissors. Hyunsoo encounters a lady who looks very similar to his favorite adult streamer while delivering food to her. He gradually begins to believe that the lady is indeed the streamer and tries to contact her. Sumi needs to buy a luxury bag for her boyfriend’s birthday. But the bag is too expensive for her to purchase. So, she makes a unique trade with a wizard. Ji-Eun, who lives with her ill boyfriend, goes out every night but her daily life collapses when she brings a guy she meets at a jazz bar to her house.','2025-03-13','ko','/djnHdHdwiLGYYuUydOSykpp8kdl.jpg','',0,0,0,0,22.444,'[14,27]'),(27,1421001,'The Last Birthday','Последний день рождения','A large family gather to celebrate a birthday. It would seem like a great reason to get together. But the family is just a project of one of the \"brothers\" — an experienced psychologist who is conducting an experiment to create a \"happiness formula\". He believes that manipulating others, their emotions and desires, will make them happy. However, love interferes with the mathematical calculations, which can neither be calculated nor predicted.','2025-03-13','ru','/zUjWFRvBJJkCezXzmIfj1dha34P.jpg','',0,0,0,0,22.442,'[18,53]'),(28,1422072,'Der Prank - April, April!','Der Prank - April, April!','A failed April Fool\'s joke by twelve-year-old Chinese guest student Xi Zhōu turns the lives of Lucas, who is the same age, and his family upside down.','2025-03-13','de','/iJt8QQbR0591KG6XmCXUYm3du7b.jpg','/xNga7a6H0w2a7Aa2TwF40jyjXs.jpg',0,0,0,0,22.439,'[]'),(29,1422081,'Sterben ohne Gott','Sterben ohne Gott','','2025-03-13','de','/mYMtn4ptf5YyoghgTgz2ER1TKTV.jpg','/1093RXL18CIGpzM7VsEJqjKkkGu.jpg',0,0,0,0,22.438,'[99]'),(30,1429784,'Singsot: Siulan Kematian','Singsot: Siulan Kematian','A kid defies the ancient taboo of whistling at dusk, unleashing a sinister terror tied to a cursed figure who made the same mistake. Bound by an inescapable curse, he’s thrust into a deadly race against time—because if he fails, the nightmare will become his new reality.','2025-03-13','id','/llZca2miwygKwuyWUpyONCL6VAR.jpg','/5VSrIF6njdpTHpRLF9nzOhwmFUi.jpg',0,0,0,0,22.422,'[27]'),(31,1432795,'Luv Ya, Bum!','Luv Ya, Bum!','In the ’70s, Houston was booming... except for the city’s woeful pro football team. The Oilers gambled on hiring Bum Phillips, an unconventional East Texas coach known for cowboy hats, ostrich boots, and folksy one-liners. Ditching tradition and embracing a family-first atmosphere, Bum brought in \'misfits\' and \'has-beens\' to build a winner. At its peak, Bum’s Oilers blew up into the Luv Ya Blue!’ phenomenon, with Earl Campbell and the Oilers going to war with a Pittsburgh Steelers dynasty. Bum’s success on and off the field, his humanity and unique style left a legacy now carried forward by many, including his son and grandson, celebrated coaches Wade and Wes Phillips.','2025-03-13','en','','',0,0,0,0,22.414,'[99]'),(32,1434291,'The Long Run','The Long Run','When two oddball strangers leave their lives behind to chase their Hollywood dreams, they discover that what they lack in talent, they make up for with determination and a shared delusion, leading to an unexpected friendship that will make them question the realities of chasing a dream.','2025-03-13','en','/n28AFdpqhKO5nt64QHQxClxUP4c.jpg','/b4Ml5MwXypvF9k27iPIPfykuS8C.jpg',0,0,0,0,22.411,'[18,35]'),(33,1434414,'Available Light','Available Light','The film explores notions of home and belonging in contemporary society. Comprising interviews with workers at the Edo Tokyo Open Air Architecture Museum in Tokyo, and fragments of conversations with renters in that city and London, a productive dialectic opens between the museum’s preserved historical ideal of the domestic and the often unsettling realities of temporary accommodation in modern cities. Combining trademark immersive sound design with impressionistic images and abstractions, Quaintance crafts an austere, oneiric and subtly affecting portrait of residential precarity.','2025-03-13','en','','',0,0,0,0,22.409,'[99]'),(34,1435275,'24 Hours of Grace','24 Hours of Grace','Grammy-nominated electronic artist ZHU is running out of time. Having bursted out of the dance scene in 2014 with his hit “Faded”, he finds himself a decade later at a musical crossroad. Steadily touring worldwide on the biggest stages with his band, he returns to San Francisco, a place where he grew up, to record his fourth studio album “Grace”. Inside this gothic cathedral, ZHU and his collaborators finish composing songs which are performed for an audience later that night.','2025-03-13','en','','',0,0,0,0,22.407,'[99]'),(35,1435766,'Dans l\'Ombre de Marlow','Dans l\'Ombre de Marlow','','2025-03-13','fr','/3fYi5YpnIWftnhkmoHIvFPYDzHw.jpg','/61EvNJYDQa3mTtbA4HLiy6iBLfP.jpg',0,0,0,0,22.406,'[37,12]'),(36,1437237,'Gioco pericoloso','Gioco pericoloso','Giada and Carlo are a couple with great complicity and intimacy, while each of them pursues their own career with determination.\r The young and ambitious Peter fascinates Carlo, who introduces him to the family. However, when Giada sees Peter, she has an unexpected reaction and tries in every way to remove him from their home: he could bring out some unspeakable secret from her past.\r And yet, the truth always finds a way to come out.','2025-03-13','it','/xQbyabXxKAS44yXb5BcNmInre5e.jpg','/qBwaMyVGjscDP1r0uAYkg88DDG6.jpg',0,0,0,0,22.404,'[53,18]'),(37,1437438,'Once Upon a Time in School 2: The Last Guardian','Մի անգամ դպրոցում 2: Վերջին Պահապանը','Grandfather knows more than you can imagine, but no secret stays in the shadows forever. Dark clouds are gathering over the school, it\'s time to find out who will be the hero of this story...','2025-03-13','hy','/iHOgzKgdg8yKMTCz6IN47r1jzhv.jpg','/xsMydIb1kE5AaDeqS46fntOCpQK.jpg',0,0,0,0,22.402,'[]'),(38,1438208,'Blind Vacation','Відпустка наосліп','In the center of the plot is the story of a successful Kyiv businesswoman, who is respected by the management and hated by the entire team. So, to get a little rest from shefini, her subordinates send her on a forced vacation: to the top of the Ukrainian Carpathians. There, the heroine is waiting for a lot of surprises, adventures and unexpected acquaintances. This vacation turns the characters \' lives upside down and changes everything forever.','2025-03-13','uk','/rj6DNIRuhJvuP1cLA31NYtmLZGo.jpg','/dgZx99O6QMNZgZpaep4OTog7FRE.jpg',0,0,0,0,22.4,'[35,10749]'),(39,1438502,'Kozha: New adventure','Қожа: Жаңа саяхат','Coming soon','2025-03-13','kk','/h8mgMiUTpvLpZyresQO8uRXB4RG.jpg','',0,0,0,0,22.399,'[10751,12]'),(40,1438696,'Laia','Laia','Laia needs help, so she decides to gather four mysterious characters for a meeting that quickly spirals out of control.','2025-03-13','es','/tVLDSmIbXzqhUJfHFdzPOgINFF0.jpg','/m7hhlBa2UBiXkQeOUxyBMl1jjeY.jpg',0,0,0,0,22.398,'[35]'),(41,1438546,'Angler','Angler','Following the recent death of her sister Ivy, Violet cleans out Ivy’s apartment with the hope of finding some peace. She gets more than she bargained for when a mysterious camera reveals to Violet that Ivy’s troubles were more complicated than they initially appeared, suggesting that someone…or something… may have been behind her untimely end.','2025-03-13','en','/c21YwjiFsVP0xYw6kx1msNmBRMX.jpg','',0,0,0,0,22.398,'[]'),(42,1440639,'Last will','Última voluntad','A wealthy family gathers for the reading of Eduardo Tejada\'s will','2025-03-13','es','/3xhwYGdZxnoI5JELuLZKs7TB1kd.jpg','',0,0,0,0,22.394,'[35,10751]'),(43,1442764,'Epílogo','Epílogo','A young man runs to try to get on the bus, he can\'t catch it so he has to wait for the next one; while he waits a girl accompanies him at the bus stop.','2025-03-13','es','/ArCT2H6t1XnbNJDnzOoaD5Nf9bk.jpg','/2ta5MfmpxFSnSTOPno7sbdapgBN.jpg',0,0,0,0,22.388,'[18]'),(44,1442388,'Bukan Jodoh Biasa Nih','Bukan Jodoh Biasa Nih','Tells the story of Richard, Jonggi and Lingga, three miskom students who are trying to overcome routine financial problems. Of the many solution options that they often debated, they finally came up with one method that made Richard and his friends take a desperate path. Serve Mr. Brandon\'s challenge to get a hidden secret box in exchange for money and the heart of his daughter, Marsya.','2025-03-13','en','/vwQBsapRSSKuGefT2W3qXIrt56v.jpg','',0,0,0,0,22.388,'[18,35,10749]'),(45,1442386,'Uwentira: Kota Jin','Uwentira: Kota Jin','A woman named Dewi visited the city of Palu to look for Salena, her acquaintance. When she arrived at the village, Tiara, her friend, welcomed Dewi warmly. However, Tiara\'s expression turned cold for a split second when Dewi said the word \"Uwentira\". Tiara\'s panic increased when she slowly realized the strange behavior of her old friend. A few seconds later, Tiara was sure that the Goddess in front of her now was not the Goddess she knew.','2025-03-13','en','/1ejZLOpStxnw2RhtlxNHuQ9bJoa.jpg','',0,0,0,0,22.388,'[27]'),(46,1269298,'The Fulcrum','Точка опоры','A successful film artist plans to go to his hometown for his sister’s wedding, accompanied by a movie star. With his arrival, he is going to humiliate his hated fiancé, the fat man and the slacker Shurik. But a quarrel with the actress ruins not only all his plans, but also radically changes his life. A true story of a selfish macho\'s reassessment of values.','2025-03-13','ru','/sYOnVTrE5JbBTfsRcaagKLV5Nc4.jpg','',0,0,0,0,22.355,'[18,10749]'),(47,1271724,'Man and Woman','Мужчина и женщина','Poignant stories about men and women who have linked their lives — some for years, some for an hour, some for five minutes. Life stories that sound at home in the kitchen, in a compartment with strangers, in a taxi, or left in a notebook as a memory, because if the feelings are real, sincere, then it\'s forever. Moments of strange encounters and bitter breakups, in which you can see something familiar.','2025-03-13','ru','/xqGlDndf1K0CnB6xrXirIjimYbt.jpg','/dPbrBB01nNl4oDJFOWvkUMoDOHR.jpg',0,0,0,0,22.349,'[18]'),(48,1013601,'The Alto Knights','The Alto Knights','Two of New York\'s most notorious organized crime bosses, Frank Costello and Vito Genovese, vie for control of the city\'s streets. Once the best of friends, petty jealousies and a series of betrayals place them on a deadly collision course that will reshape the Mafia (and America) forever.','2025-03-14','en','/95KmR0xNuZZ6DNESDwLKWGIBvMg.jpg','/4HnBkc45h6ABO9i6rbPHTqlKUu8.jpg',0,0,0,0,21.486,'[18,80]'),(49,1422166,'The Age of Disclosure','The Age of Disclosure','Director Dan Farah got 34 senior members of the U.S. Government, military, and intelligence community to come on camera. He says they reveal an 80 year cover-up of the existence of non-human intelligent life and a secret war amongst major nations to reverse engineer technology of non-human origin. The film explores the profound impact the situation has on the future of humanity, while providing a look behind-the-scenes with those at the forefront of the bi-partisan disclosure effort.','2025-03-14','en','/qsV4QTjO1jLLezzPA8yRm207ymb.jpg','/75RPFgjv5nCmxR9xJcvvOJrcsAS.jpg',0,0,0,0,21.274,'[99]'),(50,1442538,'Elevator Lady','Elevator Lady','An elevator lady who uses her body to earn more money. She falls for a wealthy married man without her knowing that this will soon lead to her downfall.','2025-03-14','tl','/4Q0eicxd5fq9llcoY2Mf8uUEE5r.jpg','/64jleJJyZj23dj8gpClAn8y6fX5.jpg',0,0,0,0,21.192,'[10749]'),(51,1442417,'A Murder in Oakland: Beauty is Deadly','A Murder in Oakland: Beauty is Deadly','Recently cleared of an embezzlement charge, Detective Williams (Marcus D Spencer) is handed a high-profile murder case while also forced to take on a new partner. Williams is trying to solve this case while also working to see if he can trust his partner.','2025-03-14','en','/iGz5PJNLHKZnWI2x36kP8igIZOe.jpg','/IwADj3Pn2s9SLSthhBxZp3X53g.jpg',0,0,1,1,21.192,'[18,35,80]'),(52,1440144,'La deuda','La deuda','','2025-03-14','es','/cZkT8i9Z2yM38UMEDpqMIvcXm5D.jpg','/yWRYg5M2iEkcZpepQNMfKCs50gt.jpg',0,0,0,0,21.192,'[18]'),(53,1419826,'The World Will Tremble','The World Will Tremble','The incredible, untold true story of how a group of prisoners attempt a seemingly impossible escape from the first Nazi death camp in order to provide the first eyewitness account of the Holocaust.','2025-03-14','en','/nSVqv6Bx0fDZS55SynC7Kxspw2r.jpg','/c5HfaZXhXCv1jwWBYuyD8xPOW3M.jpg',0,0,0,0,21.192,'[18,10752]'),(54,1443002,'Maadan Kodai Vizha','மாடன் கொடை விழா','Determined to revive a long-forgotten tradition, Murugan embarks on a mission to organize the annual Sudalai Madan ceremony, which has been defunct for years. However, his efforts are met with fierce resistance from various quarters.  Adding to the challenge, Murugan\'s girlfriend lays down an ultimatum: she will only marry him if he succeeds in pulling off the ceremony. Against all odds, Murugan perseveres, rallying the village community to support his cause. Will he triumph in his quest, and how will he overcome the hurdles to successfully organize the ceremony?','2025-03-14','ta','/4WlEM39rC5glXBuGsm5ApqXjbzd.jpg','/aLKFFq7zyvIaQE1zvlx1fsm348a.jpg',0,0,0,0,21.189,'[18]'),(55,1441567,'Warden','Warden','A docu-style science fiction thriller exploring the real-world impact of a young man discovering his superpowers. It delves into how his presence influences society, attracting followers, sparking conflict, and changing the lives of everyone around him.','2025-03-14','en','/fn5PCbsOJy25k2p7TJ7pbBSqnoM.jpg','/kyFYCrZTQBoLCePqAppG1ao18BP.jpg',0,0,0,0,21.189,'[878,53]'),(56,1440087,'Скрити в мрака','Скрити в мрака','','2025-03-14','bg','/2kjoayUhf8Uta1GmIiuGTSkGICS.jpg','/fXcWrJdBVGGhmAoUPltieJJFFxF.jpg',0,0,0,0,21.189,'[27]'),(57,1441571,'Delicate matter','Subtilus reikalas','A professor of anatomy believes that the work of scientists on humans should be more open to the public, so he lets young filmmakers into his daily life. In an attempt to look at what happens to the body after death, a portrait of the anatomist himself slowly unfolds. But how close are they allowed to get?','2025-03-14','lt','/eSWdsuwlgy8jrpHh5ThirP4vsD7.jpg','',0,0,0,0,21.186,'[99]'),(58,1439254,'Terre Rouge - Topographie du poète','Terre Rouge - Topographie du poète','Gaston Rollinger, an elderly poet and film-maker, lives alone in his childhood home in the astonishing landscape of Esch-sur-Alzette, a very special place where industrial relics meet wild nature. He draws all his inspiration from this place, and tells Fränz Hausemer many of his secrets, even though some of his landmarks are gradually beginning to disappear. This portrait of a singular man is interspersed with spellbinding pieces, the contours of which are drawn from Rollinger’s own poetry.','2025-03-14','fr','/YR5MywFwR7DdzBeNMmfdt8WEbC.jpg','',0,0,0,0,21.186,'[]'),(59,1438217,'TNA Sacrifice 2025','TNA Sacrifice 2025','The 2025 Sacrifice is an upcoming professional wrestling event produced by Total Nonstop Action Wrestling. The event will take place on March 14, 2025, at the El Paso County Coliseum in El Paso, Texas, and air on TNA+. It will be the 16th event under the Sacrifice chronology. Wrestlers from WWE\'s NXT brand, with which TNA has a partnership, will also appear at the event.','2025-03-14','en','/nxRgBBzxc55EQdeg3qXCCJfCCu.jpg','/q4NXTR3zmwkiX7a4saxVL26T0Vi.jpg',0,0,0,0,21.186,'[]'),(60,1437979,'Prisoners of Fire','Prisoners of Fire','June 26,1990, the Dude Fire rages across Zane Gray country in the towering ponderosa forests below the Mogollon Rim in Central Arizona, killing five prison crew members and a female supervisor on her first fire. Follow along with the survivors and firefighters as they share their experience as inmate firefighters and their harrowing story of courage, loss and redemption.','2025-03-14','en','/cH9GPeakTbqyssUmOhlB7WEeK48.jpg','',0,0,0,0,21.186,'[99,18]'),(61,1405338,'Demon City','Demon City 鬼ゴロシ','Framed for his family\'s murder and left for dead, an ex-hitman will stop at nothing to exact revenge on the masked \"demons\" who have taken over his city.','2025-02-26','ja','/g5PqsFFrayyRL1Ldgib2lMYuJXg.jpg','/hD2SN5bbqxk0kcRmsATJkXObgnZ.jpg',0,0,6.9,141,12.685,'[28,80,14,53]'),(62,1043808,'Vitória','Vitória','Inspired by a real woman, who filmed for two years, hidden, the routine of drug dealers on Ladeira dos Tabajaras, in Copacabana, in 2004. At the time, the material was passed on to the police, who opened an investigation and carried out an operation that resulted in in the arrest of more than 30 people, including military police involved with the gang.','2025-03-13','pt','/tiIwRMsmJnzXuCdPu38lCscgCS7.jpg','/cKIH5oCwpAGqCdIrBDrohPJJkwb.jpg',0,0,9,1,22.814,'[18]'),(63,1384565,'Anjila','अन्जिला','The film draws inspiration from the life of Anjila Tumbapo Subba, the goalkeeper of the Nepal women’s national football team. Anjila herself is in the lead role, sharing the screen with actors Dayahang Rai, Miruna Magar, Srijana Subba and others.','2025-03-13','ne','/nnJl15h9biAgCpZ6gYFof0KMD4E.jpg','',0,0,0,0,22.537,'[18]'),(64,1380415,'The Last Supper','The Last Supper','A powerful cinematic Biblical journey that brings to life the ultimate act of love and sacrifice as seen through the eyes of those who walked alongside Jesus.','2025-03-14','en','/3VLE1WoexFHL4NpR1LYU9ds0UaI.jpg','/aFa7ucmI7ZF6aNsVaoLjmfhM1fr.jpg',0,0,0,0,21.109,'[18,36]'),(65,1013482,'Borderline','Borderline','A helplessly romantic sociopath escapes from a mental institution and invades the home of a \'90s pop superstar. He just wants to be loved; she just wants to survive.','2025-03-14','en','/z2yAWt1aAvhxap9mdjlQhXiEJT4.jpg','/gKqeUlwYiZBDbFU5gT0ev7W3Vzs.jpg',0,0,6,2,21.066,'[53,35,27]'),(66,1353002,'What We Wrote Together','Lo que escribimos juntos','Mariano and Juan have been dating for several years; they have a dog and a quiet life. Mariano always wanted to have a small plant nursery away from the city and now that Juan’s work as a writer is more established due to the success of his latest novel, they decide to make that change. While they adjust to their new space and their new routines, they receive a visit from Juan\'s best friend, who has news to tell them.','2025-03-13','es','/vIZuwXUvgUPfZFYYduXyJkQ71Ld.jpg','/6bro7hHYoghblrjAs8NQfvWwLNB.jpg',0,0,0,0,22.625,'[18,10749]'),(67,1000085,'Morlaix','Morlaix','A young high school student marked by the recent death of her mother, Gwen, spends her time with her group of friends, including her lover Thomas, an apprentice baker. When Jean-Luc, a Parisian student who looks like an artist, moves into the area, Gwen does not hide her trouble, as if a decisive life choice was before her. One day, she discovers a film at the cinema that seems inexplicably inspired by her own life. Will she find the answers she is looking for?','2025-03-14','fr','/nUTE76LKG45ntFkgGFz1lpluzQR.jpg','/dlTbHQ8vO7qqTX4E1tfPUYzGlfQ.jpg',0,0,0,0,21.035,'[18]'),(68,800367,'The Actor','The Actor','Paul Cole finds himself stranded in a mysterious small town with no memory of who he is or how he got here. As bits and pieces of his past slowly emerge, he attempts to find his way home, but time is slippery, appearances can\'t be trusted, and it\'s unclear which of his identities is real.','2025-03-14','en','/jp397HSWa7e7lIkM19rvizHfTbL.jpg','/wrj9UtHdBHVBKP9nkecvaQtPj9W.jpg',0,0,0,0,21.035,'[18,9648,53]'),(69,1433813,'Sister\'s Keeper','Sister\'s Keeper','A horror short film.','2025-03-14','en','','',0,0,0,0,21.178,'[27]'),(70,1431744,'Battle King!! Map of The Mind Part 2','BATTLE KING!! Map of The Mind 終奏','','2025-03-14','ja','/GxwDgOay2EbERIwvrITFHaAhFs.jpg','',0,0,0,0,21.178,'[]'),(71,1432101,'müssen müssen','müssen müssen','','2025-03-14','de','/361LsDbpmOBVu5r0kqhoT6OYtw5.jpg','/uXEO14VpvfaCxRLWeHCLfYKCcKC.jpg',0,0,0,0,21.176,'[16,35,10402]'),(72,1431328,'Cereal Bowl','Cereal Bowl','A boy discovers a fault in his normal day-to-day life.','2025-03-14','en','','',0,0,0,0,21.176,'[14]'),(73,1428780,'Last Resort','Last Resort','Two men star in a never-ending television show, but one grows increasingly paranoid and desperate to reclaim his autonomy.','2025-03-14','en','/2eVlSCxXZlbZGD7XhBcPNCFGUli.jpg','/gPqAbR8rvKL7tTcjmRojzChWzvR.jpg',0,0,0,0,21.172,'[18,53]'),(74,1428541,'Machine de rêve','Machine de rêve','Two sailing passionates build an ice canoe, igniting the spark of a rediscovered memory for a rich culture that is still very much alive.','2025-03-14','fr','/hmCSvZty05pwLdSbCJ21HBLjE4K.jpg','/dXYnBUiydjiJxtAwt56hcMz8ktD.jpg',0,0,0,0,21.169,'[99]'),(75,1425892,'STEP OUT','STEP OUT にーにーのニライカナイ','Set against the vibrant and culturally rich backdrop of Okinawa, Step Out tells the inspiring story of Teruya, a young boy who discovers his passion for dance. Living with his dedicated single mother, Akane, and his introverted younger sister, Mai, Teruya finds himself drawn to dance after meeting Lisa, a skilled dancer at a local school. As Teruya hones his skills and partners with Lisa, his growing talent opens the door to both exciting opportunities and unexpected challenges.','2025-03-14','ja','/228se3JN0viTUd2B9XwHgDTnC86.jpg','',0,0,0,0,21.169,'[18]'),(76,1424217,'Court - State Vs. A Nobody','కోర్ట్ - State Vs. A Nobody','A determined lawyer takes on a high-stakes case to defend a 19-year-old boy, challenging a system that has already branded him guilty.','2025-03-14','te','/4pEX67LJd7ZIqYWtksBtOgQEGcQ.jpg','/efMmUfbqfMTtheqjcWiHDtxcXbA.jpg',0,0,0,0,21.169,'[18,10749]'),(77,1426337,'Fleeting','Fleeting','A dreamer who wants to fly around the world meets an unambitious heir with whom she forges an improbable romance.','2025-03-14','tl','/8dLXLQpjDUt6MwXiVHT3rqjG4Rs.jpg','',0,0,0,0,21.168,'[10749,35]'),(78,1424565,'Down We Go','Down We Go','A Countdown. A Chance?','2025-03-14','en','/toxjx90Q2ERDtMABDdcGhRKcxQr.jpg','/tMKyEvlIP4hg19R6dtgilrsWKIl.jpg',0,0,0,0,21.168,'[18]'),(79,1424352,'Taympers','Taympers','An innocent child Yumi is suddenly introduced to the world of womanhood when she witnesses her older sister Chloe feel pain in her body.','2025-03-14','en','/ptAQ9vlCGv7uSgMkLPZzPYkuMKH.jpg','/33yXWNsQK272i9NhbbXv0dC30ED.jpg',0,0,0,0,21.168,'[35]'),(80,1424103,'Checkmate','Checkmate','','2025-03-14','en','/8Vzbj4wGOgF18qd1PWYwlNToi6K.jpg','',0,0,0,0,21.164,'[]'),(81,1423093,'Tafers Code','Tafers Code','Tafers Code follows five teenagers at the T.A.F. language school in Itaquaquecetuba, guided by the charismatic Teacher Gilmar. Each episode explores the unique challenges and strengths of the students as they discover how learning English can transform their lives. With humor, emotion, and a touch of documentary style, the series culminates in a final project that inspires not only the characters but everyone to take the first step toward a brighter future through language learning.','2025-03-14','en','/75JMHtf4Ob4p7gyFfiI4p3QYk7A.jpg','/zKRZa1vIgHZJdM0ETxULRj3oya8.jpg',0,0,0,0,21.164,'[35,18,99]'),(82,1422471,'Dexter','Dexter','Aadi and Yamini\'s love story takes a tragic turn when Yamini is kidnapped and brutally murdered, plunging Aadi into despair. Struggling with PTSD, he undergoes a memory-erasing treatment and starts anew, reuniting with his childhood friend Bhuvi. However, their lives are upended when Bhuvi\'s family is taken hostage by a dangerous man named Sadhik. In a tense showdown, Sadhik traps Aadi, Bhuvi, and others in a deadly game, revealing the dark motives behind a string of murders, including Yamini\'s. Will Aadi uncover the truth and find redemption amidst the chaos?','2025-03-14','ta','/6jLbZlzNOfHQgD0a1wgtBuscriZ.jpg','/gwavBG1hohzAKB6Nb3Z0LgeDfzQ.jpg',0,0,0,0,21.164,'[53]'),(83,1422235,'Let\'s Go Somewhere Else','Let\'s Go Somewhere Else','Five years of silence end when former high school best friends, Ethan and Gio, both cramming for finals, unexpectedly reunite at a cafe. With the cafe closing early, they must go somewhere else, confronting the unresolved pain of their fractured past.','2025-03-14','tl','/64ct5c880qyekgTiwvg8dNBsAz6.jpg','/fKqQQZmvjhb8TJErwZFd4C9nPnw.jpg',0,0,0,0,21.164,'[18]'),(84,1421781,'Alleine (+1)','Alleine (+1)','','2025-03-14','de','/jzrVZF8jhKWdmJkPXdP0hTlW3Ia.jpg','/2vdwsOVgBQoct4Luq7bKtry7fN.jpg',0,0,0,0,21.164,'[18]'),(85,1421053,'A Girl & Her Guard Dog','お嬢と番犬くん','Senagaki Isaku will be a first-year high school student starting in spring. Her grandfather is the third head of the Senagaki group, a yakuza organization, so she is feared by those around her. However, starting from spring, she hopes to make normal friends and normally fall in love. She is admitted into a high school further from her hometown, however, the overprotective young head of the Senagaki group, Utou Keiya, (26 years old) falsifies his age and enters the school with her through a backdoor admission…?! Keiya proclaims that love is too early for her although Isaku is perfectly ready. In truth, she has held an unrequited love for Keiya for quite some time.','2025-03-14','ja','/bvbLBGPFhamZ1qNNxeMOxAX878G.jpg','/eejUWKVADZuHXccBuaxhDunVipK.jpg',0,0,8,1,21.164,'[18,10749]'),(86,1275248,'Sister Midnight','Sister Midnight','In Mumbai, an arranged marriage spirals into darkness as the spineless husband watches his wife morph into a ruthless, feral force within their marital confines.','2025-03-14','en','/lXMJ6un3SZvRq8cOHap7LviY5hG.jpg','/b1Pms8IQTCzZimyliCx8CFeqfSa.jpg',0,0,0,0,21.164,'[35,18,27]'),(87,1417677,'Bill Burr: Drop Dead Years','Bill Burr: Drop Dead Years','In what might be his most personal and introspective hour yet, Bill offers hilarious takes on everything from male sadness to dating advice.','2025-03-14','en','/dlH5f6BXK8C0m1OV6ExsGit8l8e.jpg','/zBKbtf2M7wyThxjrqFO9QGCv5MP.jpg',0,0,9,2,21.162,'[35]'),(88,1416501,'DNA','DNA','','2025-03-14','ta','/lO8Y1Flrhh090p93whgir2DUAot.jpg','/3dR0lgTgfzGt3PYutHwm4FvCGtU.jpg',0,0,0,0,21.157,'[18]'),(89,1399896,'Art Attack! The Dissection of Terrifier 3','Art Attack! The Dissection of Terrifier 3','Described to be \'a full dive into how the Terrifier 3 team brought various brutal kills and bloody effects to life in the latest slasher entry\'. The documentary features interviews with director Damien Leone, producer Phil Falcone, and various cast members, along with new footage from the set.','2025-03-14','en','/twNL1SF1Dne6Yp1tv6rQSDiTHyF.jpg','',0,0,0,0,21.137,'[99]'),(90,1386047,'My Partners','Minu kallimad','Three couples from Estonia and Germany navigate the uncharted territory of free love, finding new partners without ending their current relationships. On their journey they seek the help of mentors, psychologists, shamans, dancers and meditation experts. Over the course of several years, filmmaker Eva Kübar observes their sexual intimacy, desires and insecurities without ever judging their personal choices.','2025-03-14','et','/7JdFCKQQp5ee21ggDKOAUwziXDg.jpg','/z0e0NLYTw1scnuKkrqTO2F9dqgl.jpg',0,0,0,0,21.115,'[99]'),(91,1371370,'Skarlett','Skarlett','Paying homage to 70\'s grindhouse and B-Movies with music by The Brujas, this music video follows a cannibal bassist that seeks her next victim in a sleazy bar, using her charms to seduce him and then eat him alive, a character introduced in the band\'s previous single: \"Caníbal\".','2025-03-14','es','/tSJZe7yAlCB8FSePeg1IqQYDv9B.jpg','/foe9jC7vtQxqIxE6lPq0nnTckU0.jpg',0,0,0,0,21.095,'[10402,27]'),(92,1220028,'Beginning of a New Era','Beginning of a New Era','Documentary film of indigenous Mayan message of Unity and Hope for Humanity for these new times','2025-03-14','en','/fTA2LAiDyIQlUwo3giWrlFVKn26.jpg','',0,0,0,0,21.095,'[99,10402]'),(93,1208803,'The Regulars','The Regulars','Set in London\'s iconic Prince Charles Cinema, The Regulars follows a day in the life of its hapless employees. During their shift they watch movies, argue with customers, and, above all, deal with each other.','2025-03-14','en','/uXcTWEMxpKGRzhBTJkFdFAYJnab.jpg','/eJpNYNXB98hIK2s97hQKvtY2CJw.jpg',0,0,0,0,21.081,'[35]'),(94,1203524,'Penguin Girl','命中註定那頭鵝','Moon loves penguins. Her lifelong ambition is to study penguins in Antarctica. She believes she’ll meet her destined mate just like penguins do. One day, Moon runs into Adley, a guy in a penguin suit fortuitously making penguin courtship gestures at her. She believes the penguin-scented Adley is her fate. As they spend time together, Adley is moved by Moon\'s genuineness and passion. Just when their relationship has made some progress, Moon is recommended for an exchange program to the UK, throwing Moon into a dilemma between pursuing love and her dream.','2025-03-14','zh','/9kx1l6rPfju36Auqxj4FrDYJzhg.jpg','/2YpNYJTqhwZT1Vka4DzQfk1jvUi.jpg',0,0,0,0,21.076,'[18,10749]'),(95,1339790,'Cupcakes, Lonely Cats','寂寞貓蛋糕','Liu Hui is a widower whose son lives in America. She insists on living alone in the house she shared with her late husband, a calligrapher, and is surrounded by fond memories. As she gradually joins community activities, she strikes up an acquaintance with the kind and shy building caretaker who faces a quandary over a stray cat. Small moments together reveal loneliness and companionship.','2025-03-14','zh','','/2uBo2Q2BSMvbTOo27fgB0VTCtKo.jpg',0,0,0,0,21.062,'[18]'),(96,1322218,'Mononoke the Movie: The Ashes of Rage','劇場版モノノ怪 第二章 火鼠','Second installment of the Mononoke movie trilogy.','2025-03-14','ja','/bT2qcTXVNUbeIMjbggB14Wyymgi.jpg','',0,0,0,0,21.062,'[16,14,9648,27]'),(97,1330596,'The Enemy\'s Gift','Inimigo Revelador','Victor has unfinished business with his former psychoanalyst Carmo. After years of holding a grudge, he lures Carmo into his house in order to finally take vengeance.','2025-03-14','pt','/twEjPAErx23tRBSOVfvziSNbRJf.jpg','',0,0,0,0,21.055,'[18]'),(98,1326693,'Wujek foliarz','Wujek foliarz','Kuba is undergoing mandatory addiction therapy when he is kidnapped by his eccentric uncle – a conspiracy theorist who believes in the imminent end of the world. The uncle and his team of journalists from the \"Prawda TV\" channel want to involve him in their secret plan to prove that the mayoral elections were rigged. Initially skeptical of his uncle\'s obsession, Kuba discovers that the village is threatened with a real ecological disaster and decides to act. The situation is further complicated by his former love, Gośka. All this forces him to take matters into his own hands and make decisions that he has been running away from so far.','2025-03-14','pl','/m7KL3ufmOQyf8LSgQ87FPNKKw4v.jpg','/DwRNhzn6yidczoiBZwZy8gdD64.jpg',0,0,0,0,21.049,'[35]'),(99,1306707,'I Don\'t Like It Here','I Don\'t Like It Here','A recently paroled outsider returns to his desolate hometown, only to find a community plagued by a disturbing darkness. As he grapples with his own past and the town’s sinister secrets, he becomes the prime suspect in a series of gruesome murders.','2025-03-14','en','/bdwrJZ0Ue9I3M8OsTP3FuFSbpB.jpg','',0,0,0,0,21.02,'[27,9648,53]'),(100,1306284,'Wolfgang (Extraordinari)','Wolfgang (Extraordinari)','Wolfgang, a 9-year-old boy with an IQ of 125, is forced to live with his father, Carles, whom he has never seen, after the sudden death of his mother. He has one obsession, to run away to Paris to study at the Grimald Academy and become the best pianist in the world. But what Wolfgang doesn’t know is that the biggest challenge is right in front of him and that is to get along with his father.','2025-03-14','ca','/b0PxbVc7lcLDzoWU8m2E74h8VD7.jpg','',0,0,0,0,21.02,'[10751]');
